referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const find = (n, p) => {
    if (n.id === d.id) return p;
    for (let i = 0; i < n.children.length; i++) {
      const q = find(n.children[i], p.concat(i));
      if (q) return q;
    }
    return null;
  };
  const p = find(d.source, []);
  if (p === null) return null;
  let n = d.target;
  for (const i of p) n = n.children[i];
  return n.id;
}

